import json
from typing import List, Set, Tuple

def flood_fill_0s(grid: List[List[int]], start: Tuple[int, int]) -> Set[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0])
    visited = set()
    stack = [start]
    while stack:
        r, c = stack.pop()
        if (r, c) in visited:
            continue
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] != 0:
            continue
        visited.add((r, c))
        stack.extend([(r+1, c), (r-1, c), (r, c+1), (r, c-1)])
    return visited

def find_connected_components(grid: List[List[int]]) -> List[List[Set[Tuple[int, int]]]]:
    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2 and (r, c) not in visited:
                comp = set()
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited or grid[cr][cc] != 2:
                        continue
                    visited.add((cr, cc))
                    comp.add((cr, cc))
                    stack.extend([(cr+1, cc), (cr-1, cc), (cr, cc+1), (cr, cc-1)])
                components.append(comp)
    return components

def is_enclosed_frame(grid: List[List[int]], component: Set[Tuple[int, int]]) -> Set[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0])
    start_r, start_c = 0, 0
    while start_r < rows and grid[start_r][start_c] != 0:
        start_r += 1
        if start_r >= rows:
            start_r, start_c = 0, cols - 1
        if start_c >= cols:
            start_r, start_c = rows - 1, 0
        if start_r >= rows:
            break
    outside_zeros = flood_fill_0s(grid, (start_r, start_c))
    adj_zeros = set()
    for r, c in component:
        for dr, dc in [(1,0), (-1,0), (0,1), (0,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0:
                adj_zeros.add((nr, nc))
    interior = adj_zeros - outside_zeros
    return interior if interior else set()

def transform(grid):
    result = [row[:] for row in grid]
    components = find_connected_components(grid)
    for component in components:
        interior_zeros = is_enclosed_frame(grid, component)
        for r, c in interior_zeros:
            result[r][c] = 8
    return result

