    components = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2 and (r, c) not in visited:
                comp = set()
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited or grid[cr][cc] != 2:
                        continue
                    visited.add((cr, cc))
                    comp.add((cr, cc))
                    stack.extend([(cr+1, cc), (cr-1, cc), (cr, cc+1), (cr, cc-1)])
                components.append(comp)
    return components

